args.new_string:
    PARTS:
    // Address decode (2-bit sel for DMux4Way / Mux4Way16):
    //   address[14]=0                 -> 00 -> RAM      (0x0000-0x3FFF)
    //   address[14]=1, address[13]=0  -> 01 -> Screen   (0x4000-0x5FFF)
    //   address[14]=1, address[13]=1  -> 10 -> Keyboard (0x6000, read-only)
    Not(in=address[13], out=notA13);
    And(a=address[14], b=notA13, out=sel0);
    And(a=address[14], b=address[13], out=sel1);

    DMux4Way(in=load, sel[0]=sel0, sel[1]=sel1, a=loadRam, b=loadScreen);

    RAM16K(in=in, load=loadRam, address=address[0..13], out=ramOut);
    Screen(in=in, load=loadScreen, address=address[0..12], out=screenOut);
    Keyboard(out=kbdOut);

    Mux4Way16(a=ramOut, b=screenOut, c=kbdOut, d=false,
              sel[0]=sel0, sel[1]=sel1, out=out);
}

